const trig = $('Sub-workflow Input').first()?.json || {};
const ctx = $('Resolve Tenant Context').first()?.json || {};
const scope = String(trig.scope || 'projects').toLowerCase();
const limit = Math.min(parseInt(trig.limit, 10) || 10, 50);
const recordId = String(trig.recordId || '').trim();
const query = String(trig.query || '').trim();
const orgCfg = (ctx.orgConfig && typeof ctx.orgConfig === 'object') ? ctx.orgConfig : {};
const fbCfg = (trig.fallbackOrgConfig && typeof trig.fallbackOrgConfig === 'object') ? trig.fallbackOrgConfig : {};
const cfg = Object.assign({}, fbCfg, orgCfg);
const envelope = {
  ok: false, status: 'refused', reasonCode: 'none', guidance: 'none', userMessage: null,
  connectorId: 'zoho.projects', organizationId: ctx.organizationId || null, userId: ctx.userId || null,
  contextSource: ctx.contextSource || 'fallback', degraded: ctx.degraded === true,
  records: [], total: 0, error: null,
  diagnostics: { requestId: 'zpr-' + ($execution.id || 'na') + '-' + Date.now(), workflow: 'prism-14-zoho-projects-service', scope: scope }
};
function refuse(code, msg, guidance) { envelope.status = 'refused'; envelope.reasonCode = code; envelope.userMessage = msg; envelope.guidance = guidance; return [{ json: envelope }]; }
if (ctx.enabled === false) return refuse('connector_disabled', 'Zoho Projects is turned off for you - enable it in Connections.', 'enable');
if (ctx.entitlement === false) return refuse('not_entitled', 'Your account does not have access to Zoho Projects - ask your admin to unlock it.', 'request_access');
if (!ctx.accessToken) return refuse('missing_token', 'Zoho Projects is not connected yet - connect your account in Connections to get started.', 'connect');
const dc = String(cfg.dataCenter || 'in').replace(/^zoho\./, '');
const apiBase = 'https://projectsapi.zoho.' + dc + '/api/v3';
// Accept the portal under any of the names used across the pipeline:
// server orgConfig sends portalId; org settings may use projectsPortalId.
const portalId = String(cfg.portalId || cfg.projectsPortalId || '').trim();
if (!portalId) return refuse('org_misconfigured', 'Your organization has not configured its Zoho Projects portal yet - ask your admin to set it in organization settings.', 'none');
let url = '';
if (scope === 'tasks' || scope === 'task') {
  const projectId = String(cfg.projectsDefaultProjectId || cfg.defaultProjectId || recordId || '').trim();
  if (!projectId) return refuse('empty', 'Tell me which project to look at (or set a default project in organization settings) to browse tasks.', 'none');
  url = apiBase + '/portals/' + encodeURIComponent(portalId) + '/projects/' + encodeURIComponent(projectId) + '/tasks?per_page=' + limit;
} else {
  url = recordId ? apiBase + '/portals/' + encodeURIComponent(portalId) + '/projects/' + encodeURIComponent(recordId) : apiBase + '/portals/' + encodeURIComponent(portalId) + '/projects?per_page=' + limit;
}
return [{ json: Object.assign({}, envelope, { ok: true, status: 'pending', accessToken: ctx.accessToken, requestUrl: url }) }];

const res = $input.first()?.json || {};
const meta = $('Gate & Build Request').first()?.json || {};
const scope = (meta.diagnostics && meta.diagnostics.scope) || 'unknown';
const envelope = {
  ok: false, status: 'error', reasonCode: 'provider_error', guidance: 'retry',
  userMessage: 'Zoho Projects returned an error - try again shortly. If it persists, check the connection in Connections.',
  connectorId: 'zoho.projects', organizationId: meta.organizationId || null, userId: meta.userId || null,
  contextSource: meta.contextSource || 'fallback', degraded: meta.degraded === true,
  records: [], total: 0, error: null,
  diagnostics: { requestId: (meta.diagnostics && meta.diagnostics.requestId) || ('zpr-' + Date.now()), workflow: 'prism-14-zoho-projects-service' }
};
const httpStatus = (res.error && (res.error.status || res.error.statusCode)) || res.statusCode || null;
const errCode = res.error && res.error.code ? String(res.error.code) : '';
function finishSuccess() { envelope.ok = true; envelope.status = 'success'; envelope.reasonCode = 'none'; envelope.guidance = 'none'; envelope.userMessage = null; envelope.error = null; }
if (res.code === 'AUTHENTICATION_FAILURE' || res.code === 'INVALID_TOKEN') { envelope.reasonCode = 'reauth_required'; envelope.guidance = 'reconnect'; envelope.userMessage = 'Your Zoho connection needs re-authentication - reconnect in Connections.'; envelope.error = { provider: 'zoho', httpStatus: httpStatus || 401, message: String(res.code), retryable: false }; return [{ json: envelope }]; }
const raw = Array.isArray(res.projects) ? res.projects : (Array.isArray(res.portals) ? res.portals : (Array.isArray(res.tasks) ? res.tasks : (Array.isArray(res.data) ? res.data : [])));
const records = raw.map(function (d) { return {
  id: String(d.id || d.project_id || ''), name: d.name || d.project_name || '', status: d.status || d.status_name || '',
  progress: d.progress_percent != null ? Number(d.progress_percent) : (d.percentage_completed != null ? Number(d.percentage_completed) : null),
  startDate: d.start_date || '', endDate: d.end_date || '', owner: ((d.owner && (d.owner.name || d.owner)) || d.owner_name || '') + '', description: d.description || ''
}; });
finishSuccess(); envelope.records = records; envelope.total = records.length;
return [{ json: envelope }];
